  if (rrc_eutra) {
    logger.debug("Applying remaining CSI configuration.");
    phy_cfg_state = PHY_CFG_STATE_NSA_RA_COMPLETED;
    phy->set_config(phy_cfg);
  } else {
    phy_cfg_state = PHY_CFG_STATE_NONE;
  }
}

